package app.rwun;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Planning-only visual primitives; keeps recorder controls and training logic independent. */
final class PlanningUi {
 static final int CANVAS=Color.BLACK,CARD=Color.rgb(35,42,52),INK=Color.rgb(226,232,240),MUTED=Color.rgb(150,161,179),TEAL=Color.rgb(64,202,181),BORDER=Color.rgb(55,64,77);
 static int dp(Context c,int x){return UiKit.dp(c,x);}
 static GradientDrawable shape(Context c,int color,int radius,boolean border){GradientDrawable d=UiKit.shape(c,color,radius);if(border)d.setStroke(dp(c,1),BORDER);return d;}
 static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);return l;}
 static TextView label(Context c,String text,int sp,boolean bold){return UiKit.label(c,text,sp,bold?INK:MUTED,bold);}
 static void gap(Context c,LinearLayout parent,int h){parent.addView(new View(c),new LinearLayout.LayoutParams(1,dp(c,h)));}
 static void margin(Context c,View v,int top,int bottom){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(c,top),0,dp(c,bottom));v.setLayoutParams(lp);}
 static LinearLayout card(Context c){LinearLayout card=column(c);card.setPadding(dp(c,20),dp(c,18),dp(c,20),dp(c,18));card.setBackground(shape(c,CARD,18,false));margin(c,card,0,18);return card;}
 static LinearLayout choice(Context c,int icon,String title,String subtitle,Runnable click){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(c,20),dp(c,20),dp(c,18),dp(c,20));row.setBackground(shape(c,CARD,18,false));row.setMinimumHeight(dp(c,subtitle.isEmpty()?78:116));ImageView image=new ImageView(c);image.setImageDrawable(UiKit.icon(c,icon,TEAL,30));row.addView(image,new LinearLayout.LayoutParams(dp(c,38),dp(c,38)));LinearLayout text=column(c);LinearLayout.LayoutParams tl=new LinearLayout.LayoutParams(0,-2,1);tl.setMargins(dp(c,16),0,0,0);row.addView(text,tl);text.addView(label(c,title,19,true));if(!subtitle.isEmpty())text.addView(label(c,subtitle,15,false));row.setClickable(true);row.setFocusable(true);row.setContentDescription(title+(subtitle.isEmpty()?"":", "+subtitle));row.setOnClickListener(v->{UiKit.feedback(v);click.run();});margin(c,row,0,16);return row;}
 /** Compact home actions grow with accessibility text instead of clipping it. */
 static LinearLayout compactChoice(Context c,int icon,String title,String subtitle,Runnable click){
  LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);
  row.setPadding(dp(c,14),dp(c,10),dp(c,14),dp(c,10));row.setMinimumHeight(dp(c,76));
  row.setBackground(UiKit.ripple(c,CARD,16));
  ImageView image=new ImageView(c);image.setImageDrawable(UiKit.icon(c,icon,TEAL,24));
  image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
  row.addView(image,new LinearLayout.LayoutParams(dp(c,28),dp(c,28)));
  LinearLayout text=column(c);LinearLayout.LayoutParams tl=new LinearLayout.LayoutParams(0,-2,1);tl.setMargins(dp(c,12),0,0,0);row.addView(text,tl);
  TextView heading=label(c,title,16,true);heading.setPadding(0,dp(c,2),0,dp(c,2));
  heading.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);text.addView(heading);
  if(!subtitle.isEmpty()){TextView detail=label(c,subtitle,13,false);detail.setPadding(0,dp(c,2),0,dp(c,2));detail.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);text.addView(detail);}
  row.setClickable(true);row.setFocusable(true);row.setContentDescription(title+(subtitle.isEmpty()?"":", "+subtitle));
  row.setOnClickListener(v->{UiKit.feedback(v);click.run();});margin(c,row,0,8);return row;
 }
 static Button chip(Context c,String text,boolean selected,Runnable click){Button b=new Button(c);b.setAllCaps(false);b.setText(text);b.setTextSize(UiKit.textSizeSp(16));b.setTextColor(selected?TEAL:INK);b.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(c,48));b.setMinimumHeight(dp(c,48));b.setPadding(dp(c,15),dp(c,8),dp(c,15),dp(c,8));GradientDrawable bg=shape(c,selected?Color.rgb(13,54,50):CARD,14,true);if(selected)bg.setStroke(dp(c,1),TEAL);b.setBackground(bg);b.setStateListAnimator(null);b.setOnClickListener(v->click.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.setMargins(0,0,dp(c,8),0);b.setLayoutParams(lp);return b;}
 static ImageButton plainIcon(Context c,int resource,String description,Runnable click){ImageButton b=new ImageButton(c);b.setImageDrawable(UiKit.icon(c,resource,INK,28));b.setContentDescription(description);b.setBackgroundColor(Color.TRANSPARENT);b.setPadding(dp(c,12),dp(c,12),dp(c,12),dp(c,12));b.setOnClickListener(v->{UiKit.feedback(v);click.run();});return b;}
 static final class RoundedFrame extends FrameLayout{private final Path clip=new Path();private final RectF bounds=new RectF();RoundedFrame(Context c){super(c);}protected void onMeasure(int widthSpec,int heightSpec){int desired=getMinimumHeight();for(int i=0;i<getChildCount();i++){View child=getChildAt(i);if(child instanceof LinearLayout){child.measure(MeasureSpec.makeMeasureSpec(MeasureSpec.getSize(widthSpec),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(0,MeasureSpec.UNSPECIFIED));desired=Math.max(desired,child.getMeasuredHeight());}}super.onMeasure(widthSpec,MeasureSpec.makeMeasureSpec(resolveSize(desired,heightSpec),MeasureSpec.EXACTLY));}protected void dispatchDraw(Canvas canvas){int save=canvas.save();bounds.set(0,0,getWidth(),getHeight());clip.reset();clip.addRoundRect(bounds,dp(getContext(),18),dp(getContext(),18),Path.Direction.CW);canvas.clipPath(clip);super.dispatchDraw(canvas);canvas.restoreToCount(save);}}
 static FrameLayout header(Context c,int step,Runnable back,Runnable close){UiKit.Palette p=new UiKit.Palette(true);FrameLayout bar=new FrameLayout(c);bar.setMinimumHeight(dp(c,64));ImageButton left=plainIcon(c,R.drawable.ic_arrow_back,"Previous step",back);bar.addView(left,new FrameLayout.LayoutParams(dp(c,52),dp(c,56),Gravity.START|Gravity.CENTER_VERTICAL));ImageButton right=plainIcon(c,android.R.drawable.ic_menu_close_clear_cancel,"Close plan setup",close);bar.addView(right,new FrameLayout.LayoutParams(dp(c,52),dp(c,56),Gravity.END|Gravity.CENTER_VERTICAL));FrameLayout track=new FrameLayout(c);track.setBackground(shape(c,BORDER,4,false));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(c,150),dp(c,5),Gravity.CENTER);bar.addView(track,lp);View filled=new View(c);filled.setBackground(shape(c,INK,4,false));track.addView(filled,new FrameLayout.LayoutParams(dp(c,Math.max(8,Math.min(150,step*30))),-1));bar.setPadding(dp(c,10),0,dp(c,10),0);return bar;}
 static FrameLayout raceCard(Context c,org.json.JSONObject race,Runnable click){FrameLayout frame=new RoundedFrame(c);frame.setMinimumHeight(dp(c,132));frame.setBackground(shape(c,CARD,18,true));frame.setClipToOutline(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(c,18));frame.setLayoutParams(lp);if(race.optString("city").equalsIgnoreCase("Cape Town")){ImageView image=new ImageView(c);image.setImageResource(R.drawable.race_cape_town);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));}View shade=new View(c);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x99202730,0xED10151B}));frame.addView(shade,new FrameLayout.LayoutParams(-1,-1));LinearLayout content=column(c);content.setGravity(Gravity.CENTER_VERTICAL);content.setPadding(dp(c,20),dp(c,13),dp(c,40),dp(c,13));TextView date=label(c,java.time.LocalDate.parse(race.optString("date")).format(java.time.format.DateTimeFormatter.ofPattern("d MMM yyyy"))+" · "+PlanEngine.distance(race.optDouble("km")),15,true);date.setTextColor(TEAL);content.addView(date);TextView title=label(c,race.optString("name"),19,true);title.setMaxLines(3);content.addView(title);TextView place=label(c,race.optString("city")+", "+race.optString("country"),14,false);place.setTextColor(INK);content.addView(place);frame.addView(content,new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER_VERTICAL));ImageView arrow=new ImageView(c);arrow.setImageDrawable(UiKit.icon(c,R.drawable.ic_chevron_right,INK,22));FrameLayout.LayoutParams a=new FrameLayout.LayoutParams(dp(c,26),dp(c,30),Gravity.END|Gravity.CENTER_VERTICAL);a.setMargins(0,0,dp(c,12),0);frame.addView(arrow,a);frame.setClickable(true);frame.setFocusable(true);frame.setContentDescription(race.optString("name")+", "+race.optString("date")+", "+race.optDouble("km")+" kilometres, "+race.optString("city"));frame.setOnClickListener(v->{UiKit.feedback(v);click.run();});return frame;}
}
